CREATE TABLE criterion_scores (
	id INTEGER NOT NULL, 
	grade_id VARCHAR NOT NULL, 
	criterion_id INTEGER NOT NULL, 
	score FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(grade_id) REFERENCES grades (id), 
	FOREIGN KEY(criterion_id) REFERENCES rubric_criteria (id)
);
