CREATE TABLE feedback (
	id VARCHAR NOT NULL, 
	submission_id VARCHAR NOT NULL, 
	comments VARCHAR NOT NULL, 
	strengths VARCHAR, 
	improvements VARCHAR, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(submission_id) REFERENCES submissions (id)
);
