CREATE TABLE resubmissions (
	id VARCHAR NOT NULL, 
	original_submission_id VARCHAR NOT NULL, 
	new_submission_id VARCHAR, 
	reason VARCHAR NOT NULL, 
	requested_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(original_submission_id) REFERENCES submissions (id), 
	FOREIGN KEY(new_submission_id) REFERENCES submissions (id)
);
