CREATE TABLE rubrics (
	id VARCHAR NOT NULL, 
	assignment_id VARCHAR NOT NULL, 
	total_points INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_rubric_total_points_gt_zero CHECK (total_points > 0), 
	CONSTRAINT uq_rubric_assignment_id UNIQUE (assignment_id), 
	FOREIGN KEY(assignment_id) REFERENCES assignments (id)
);
